"""pt — sira_c."""

T = {
"sira_151": ("Que tio do Profeta ﷺ abraçou o islão e foi um dos seus defensores mais firmes em Meca?", ["Hamza ibn 'Abd al-Muttalib", "Abu Lahab", "Abu Talib", "Al-'Abbas"], "Hamza, tio e irmão de leite do Profeta ﷺ, abraçou o islão em Meca e foi chamado «o leão de Allah»."),
"sira_152": ("Em casa de quem se reuniam em segredo os primeiros muçulmanos em Meca?", ["Em casa de al-Arqam", "Em casa de Abu Bakr", "Em casa de Khadija", "Em casa de Abu Talib"], "A casa de al-Arqam ibn Abi al-Arqam, na colina de Safa, foi o primeiro lugar de reunião e ensino."),
"sira_153": ("Que companheiro, convertido em Meca, foi depois enviado como primeiro mestre a Yathrib?", ["Mus'ab ibn 'Umayr", "Bilal ibn Rabah", "Khalid ibn al-Walid", "Abu Hurayra"], "Mus'ab ibn 'Umayr, jovem mequense de família nobre, foi enviado a Yathrib após o pacto de 'Aqaba para ensinar o Alcorão."),
"sira_154": ("Com que ordem começa a sura Al-Muddaththir, que iniciou o apelo público?", ["«Ó tu, o envolto num manto! Levanta-te e adverte»", "«Lê, em nome do teu Senhor»", "«Combate os incrédulos»", "«Emigra para Medina»"], "«Ó tu, o envolto num manto! Levanta-te e adverte»."),
"sira_155": ("Que versículo ordenou ao Profeta ﷺ proclamar abertamente o que lhe era ordenado?", ["«Proclama, pois, o que te é ordenado»", "«Sê paciente»", "«Recita em segredo»", "«Retira-te»"], "«Proclama, pois, o que te é ordenado e afasta-te dos idólatras»."),
"sira_156": ("Onde afixou Quraish o documento do boicote contra os Banu Hashim?", ["Dentro da Caaba", "Na porta da cidade", "No mercado de 'Ukaz", "Na colina de Safa"], "O texto do boicote foi pendurado dentro da Caaba, até o pacto ser quebrado e o documento abandonado."),
"sira_157": ("No pomar de quem, em Taif, se refugiou o Profeta ﷺ e recebeu um cacho de uvas depois de ser expulso?", ["No pomar de 'Utba e Shayba, onde o servo 'Addas o serviu", "Em casa do chefe de Taif", "Numa caravana de passagem", "Em casa de um ferreiro"], "Ferido e expulso de Taif, refugiou-se num pomar onde lhe ofereceram uvas, servidas por um servo cristão chamado 'Addas."),
"sira_158": ("Que companheiro, a princípio feroz adversário, abraçou o islão e foi chamado «aquele que distingue a verdade da falsidade»?", ["'Umar ibn al-Khattab", "Abu Sufyan", "Khalid ibn al-Walid", "'Amr ibn al-'As"], "'Umar ibn al-Khattab, hostil no início, converteu-se em Meca e recebeu o título de al-Faruq."),
"sira_159": ("Em casa de que família ficou o Profeta ﷺ ao chegar a Medina, onde a sua camela se ajoelhou?", ["De Abu Ayyub al-Ansari", "De Sa'd ibn Mu'adh", "De Ubayy ibn Ka'b", "De Anas ibn Malik"], "A camela ajoelhou-se junto à casa de Abu Ayyub al-Ansari, que hospedou o Profeta ﷺ à sua chegada."),
"sira_160": ("Como se chama o cemitério de Medina onde estão sepultados muitos companheiros?", ["Al-Baqi'", "Al-Mu'alla", "Al-Hijr", "Al-Quba"], "Baqi' al-Gharqad, junto à mesquita do Profeta ﷺ, é o cemitério de Medina."),
"sira_161": ("De que mesquita diz o Alcorão que foi «fundada sobre a piedade desde o primeiro dia»?", ["A mesquita de Quba", "A Mesquita Sagrada", "A mesquita de Al-Aqsa", "A mesquita de Kufa"], "«Uma mesquita fundada sobre a piedade desde o primeiro dia é mais digna de que nela ores»."),
"sira_162": ("Em que mesquita orava o Profeta ﷺ quando foi revelada a ordem de mudar a alquibla?", ["A mesquita das duas alquiblas (Masjid al-Qiblatayn)", "A mesquita de Quba", "A Mesquita Sagrada", "A mesquita de Al-Aqsa"], "A ordem chegou durante a oração; os fiéis voltaram-se para a Caaba, daí o nome «mesquita das duas alquiblas»."),
"sira_163": ("Que obrigação foi prescrita aos muçulmanos no segundo ano da Hégira?", ["O jejum do mês do Ramadão", "A peregrinação", "A oração noturna", "A viagem a Taif"], "O jejum do Ramadão tornou-se obrigatório em Medina, no segundo ano da Hégira."),
"sira_164": ("Que companheiro viu em sonhos as palavras da chamada à oração, adotadas depois pelo Profeta ﷺ?", ["'Abdullah ibn Zayd", "Bilal ibn Rabah", "Abu Bakr", "Mu'adh ibn Jabal"], "'Abdullah ibn Zayd relatou o sonho do adhan; o Profeta ﷺ aprovou-o e encarregou Bilal de o proclamar."),
"sira_165": ("O que diz o Alcorão do punhado de terra que o Profeta ﷺ atirou em Badr?", ["«Não foste tu que atiraste quando atiraste, mas Allah»", "«Apontaste bem»", "«O vento levou-o»", "«Atiraram-no os anjos»"], "«Não foste tu que atiraste quando atiraste, mas foi Allah quem atirou»."),
"sira_166": ("Como descreve o Alcorão o estado de alguns crentes ao partirem para Badr?", ["Discutiam sobre isso como se fossem levados para a morte", "Estavam todos impacientes", "Recusaram-se a partir", "Pediram um adiamento"], "«Discutiam contigo sobre a verdade, depois de se ter tornado evidente, como se fossem levados para a morte»."),
"sira_167": ("Como recorda o Alcorão aos crentes a sua situação antes da vitória?", ["Eram poucos e oprimidos na terra, e Allah deu-lhes abrigo e socorro", "Eram ricos", "Eram numerosos", "Já governavam"], "«Lembrai-vos de quando éreis poucos e oprimidos na terra… Ele deu-vos abrigo e amparou-vos com o Seu socorro»."),
"sira_168": ("Que companheiro propôs em Badr deslocar o exército para o poço mais próximo do inimigo?", ["Al-Hubab ibn al-Mundhir", "Sa'd ibn Mu'adh", "Al-Miqdad", "Az-Zubayr"], "Al-Hubab ibn al-Mundhir perguntou se a posição vinha da revelação ou do parecer; ao saber que era parecer, propôs avançar até ao poço, e o Profeta ﷺ aceitou."),
"sira_169": ("Qual era o nome do ponto de água junto ao qual ocorreu a batalha de Badr?", ["Badr, um poço na rota das caravanas", "Zamzam", "Quba", "Al-Hudaybiyya"], "Badr era um ponto de água na rota das caravanas entre Meca e a Síria; a batalha tomou dele o nome."),
"sira_170": ("Que assunto relativo aos cativos foi tratado por revelação depois de Badr?", ["O resgate aceite pelos prisioneiros", "A partilha da água", "A escolha do acampamento", "A data do regresso"], "A passagem fala dos cativos e do resgate, e depois permite o que foi tomado como lícito e bom."),
"sira_171": ("Segundo a sura Al 'Imran, o que mudou a situação em Uhud depois de um primeiro êxito?", ["A desobediência e a disputa sobre a ordem recebida", "O número do inimigo", "O calor", "A falta de água"], "«…até que fraquejastes, disputastes sobre a ordem e desobedecestes»."),
"sira_172": ("O que diz o Alcorão daqueles que são mortos no caminho de Allah?", ["Não os julgues mortos: estão vivos junto ao seu Senhor", "Dormem até ao Último Dia", "Regressam", "São esquecidos"], "«Não julgues que os que foram mortos no caminho de Allah estão mortos: pelo contrário, estão vivos junto ao seu Senhor, bem providos»."),
"sira_173": ("Em que colina colocou o Profeta ﷺ os arqueiros em Uhud?", ["O monte dos Arqueiros (Jabal ar-Rumat)", "O monte Safa", "O monte Thawr", "O monte Hira"], "Cinquenta arqueiros foram colocados numa colina que passou a chamar-se «o monte dos arqueiros», com a ordem de não a abandonarem."),
"sira_174": ("Como descreve a sura Al-Ahzab a provação do cerco de Medina?", ["Os olhares desviaram-se e os corações chegaram às gargantas", "A cidade caiu", "Só faltaram víveres", "O céu escureceu"], "«Quando vieram a vós de cima e de baixo, quando os olhares se desviaram e os corações chegaram às gargantas»."),
"sira_175": ("Como descreve o Alcorão o desfecho da batalha do Fosso?", ["Allah repeliu os coligados cheios de ira, sem que obtivessem bem algum", "Uma longa batalha campal", "Um tratado de paz", "Uma retirada dos muçulmanos"], "«E Allah repeliu os que não creram, cheios de ira: não obtiveram bem algum, e Allah bastou aos crentes no combate»."),
"sira_176": ("Onde fica Hudaybiyya, lugar do famoso tratado?", ["No limite do recinto sagrado, a oeste de Meca", "Perto de Medina", "No Iémen", "Na Síria"], "Hudaybiyya é um lugar situado nos limites do recinto sagrado de Meca, onde o tratado foi concluído."),
"sira_177": ("Que visão do Profeta ﷺ confirma o Alcorão depois de Hudaybiyya?", ["Que entrariam seguros na Mesquita Sagrada, de cabeça rapada ou cabelo cortado", "Que venceriam em Khaybar", "Que construiriam uma cidade", "Que viajariam para a Síria"], "«Allah cumpriu a visão com que agraciou o Seu Mensageiro: entrareis seguros na Mesquita Sagrada»."),
"sira_178": ("O que recorda a sura Al-Fath sobre as mãos contidas em Meca?", ["Allah conteve as mãos deles contra vós e as vossas contra eles no vale de Meca", "Ordenou combater", "Fechou os caminhos", "Enviou uma tempestade"], "«E Ele é quem, no vale de Meca, conteve as mãos deles contra vós e as vossas contra eles, depois de vos ter dado a vitória sobre eles»."),
"sira_179": ("Em que ano da Hégira ocorreu a expedição de Khaybar?", ["No sétimo", "No segundo", "No quinto", "No décimo"], "Khaybar ocorreu no ano 7 da Hégira, o seguinte ao tratado de Hudaybiyya."),
"sira_180": ("Como se chama a 'umra realizada no ano seguinte a Hudaybiyya, segundo os termos do tratado?", ["'Umrat al-Qada", "Hajjat al-Wada'", "'Umrat al-Ji'rana", "Al-Hajj al-Akbar"], "O tratado previa que os muçulmanos voltassem no ano seguinte; essa 'umra chama-se 'umrat al-qada."),
"sira_181": ("Que soberano rasgou a carta do Profeta ﷺ ao recebê-la?", ["O rei da Pérsia (Cosroes)", "O Negus da Abissínia", "O governador do Barém", "O rei do Iémen"], "O Profeta ﷺ enviou cartas aos soberanos vizinhos; a dirigida ao rei da Pérsia foi rasgada."),
"sira_182": ("Que companheiro levou a carta do Profeta ﷺ ao Negus da Abissínia e a outros soberanos?", ["'Amr ibn Umayya ad-Damri", "Abu Hurayra", "Anas ibn Malik", "Ubayy ibn Ka'b"], "Foram escolhidos mensageiros entre os companheiros; 'Amr ibn Umayya ad-Damri foi enviado ao Negus."),
"sira_183": ("Em que direção fica Khaybar em relação a Medina?", ["A norte", "A sul", "A leste", "A oeste, junto ao mar"], "Khaybar é um oásis fortificado a norte de Medina, na rota para a Síria."),
"sira_184": ("Em que se tornou a casa de Abu Sufyan no dia da conquista de Meca?", ["Num lugar seguro para quem nela entrasse", "Numa prisão", "Num armazém", "Numa mesquita"], "O Profeta ﷺ declarou seguro quem entrasse na Mesquita Sagrada, permanecesse em sua casa ou entrasse na casa de Abu Sufyan."),
"sira_185": ("Que ano se chama «o ano da conquista» ('am al-fath)?", ["O ano 8 da Hégira", "O ano 6 da Hégira", "O ano 10 da Hégira", "O ano 2 da Hégira"], "Meca foi conquistada no ano 8 da Hégira, conhecido como o ano da conquista."),
"sira_186": ("Que batalha se seguiu pouco depois da conquista de Meca, contra as tribos de Hawazin?", ["Hunayn", "Badr", "Uhud", "Khaybar"], "Hunayn ocorreu pouco depois da conquista, num vale entre Meca e Taif."),
"sira_187": ("O que fez descer Allah sobre o Seu Mensageiro ﷺ e os crentes após o seu desconcerto em Hunayn?", ["A Sua tranquilidade (sakina), e tropas que não viam", "Chuva", "Um vento", "Um reforço de cavaleiros"], "«Depois, Allah fez descer a Sua tranquilidade sobre o Seu Mensageiro e sobre os crentes, e fez descer tropas que não víeis»."),
"sira_188": ("Para que cidade se dirigiu o exército muçulmano depois de Hunayn?", ["Taif", "Khaybar", "Tabuk", "Saná"], "Depois de Hunayn os muçulmanos cercaram Taif, cujos habitantes se tinham entrincheirado."),
"sira_189": ("Que expedição chama o Alcorão «a hora da dificuldade» (sa'at al-'usra)?", ["Tabuk", "Badr", "Khaybar", "Hunayn"], "«Allah aceitou o arrependimento do Profeta, dos emigrados e dos auxiliares que o seguiram na hora da dificuldade»."),
"sira_190": ("O que diz o Alcorão dos três companheiros que ficaram para trás em Tabuk, antes do seu perdão?", ["A terra tornou-se-lhes estreita apesar da sua amplitude, e depois Allah aceitou o seu arrependimento", "Foram desterrados", "Partiram para o Iémen", "Foram esquecidos"], "«E aos três que ficaram para trás: a terra, com toda a sua amplitude, tornou-se-lhes estreita… e depois aceitou o seu arrependimento»."),
"sira_191": ("Em que direção fica Tabuk, meta da última grande expedição?", ["A norte, para a fronteira da Síria", "A sul, para o Iémen", "A leste, para o Iraque", "A oeste, no mar Vermelho"], "Tabuk fica a norte de Medina, na rota da Síria; foi a última grande expedição do Profeta ﷺ."),
"sira_192": ("Que companheiro equipou grande parte do exército de Tabuk com os seus próprios bens?", ["'Uthman ibn 'Affan", "Sa'd ibn Abi Waqqas", "Talha ibn 'Ubaydillah", "Abu Dharr"], "'Uthman ibn 'Affan forneceu uma parte considerável do equipamento do «exército da dificuldade» (jaysh al-'usra)."),
"sira_193": ("Que companheiro foi o primeiro a disparar uma flecha no caminho de Allah?", ["Sa'd ibn Abi Waqqas", "Az-Zubayr ibn al-'Awwam", "Talha ibn 'Ubaydillah", "Abu 'Ubayda"], "Sa'd ibn Abi Waqqas, dos primeiríssimos muçulmanos, é conhecido como o primeiro a disparar uma flecha no caminho de Allah."),
"sira_194": ("Que companheiro é chamado «o discípulo (hawari) do Mensageiro de Allah ﷺ»?", ["Az-Zubayr ibn al-'Awwam", "Abu Hurayra", "Salman al-Farisi", "Bilal"], "Az-Zubayr ibn al-'Awwam, primo do Profeta ﷺ, foi chamado o seu hawari, o seu apoio próximo."),
"sira_195": ("A que companheiro foi confiado o conhecimento dos hipócritas, sendo por isso chamado «o guardião do segredo»?", ["Hudhayfa ibn al-Yaman", "Abu Musa al-Ash'ari", "'Ammar ibn Yasir", "Abu ad-Darda"], "Hudhayfa ibn al-Yaman é conhecido como «sahib as-sirr», aquele a quem o Profeta ﷺ confiou o que sabia dos hipócritas."),
"sira_196": ("De que terra vinha Salman, chamado «al-Farisi», que propôs o fosso?", ["Da Pérsia", "Do Iémen", "Da Abissínia", "De Bizâncio"], "Salman, de origem persa, procurou longamente a verdade antes de se juntar ao Profeta ﷺ em Medina."),
"sira_197": ("Que mulher, mãe de Anas ibn Malik, ofereceu ao Profeta ﷺ o serviço do seu filho?", ["Umm Sulaym", "Umm Salama", "Umm Ayman", "Umm Habiba"], "Umm Sulaym, dos ansar, apresentou o seu filho Anas ao Profeta ﷺ para o servir quando chegou a Medina."),
"sira_198": ("Que esposa do Profeta ﷺ foi conhecida pelo seu grande saber e transmitiu numerosos hadices?", ["'Aisha", "Sawda", "Juwayriya", "Maymuna"], "'Aisha, filha de Abu Bakr, é uma das maiores transmissoras de hadices e uma referência em ciência religiosa."),
"sira_199": ("Que esposa do Profeta ﷺ era sua prima e o seu casamento é mencionado na sura Al-Ahzab?", ["Zaynab bint Jahsh", "Hafsa", "Umm Salama", "Safiyya"], "O casamento com Zaynab bint Jahsh é mencionado na sura Al-Ahzab (33:37)."),
"sira_200": ("Que esposa do Profeta ﷺ aconselhou o que desbloqueou a crise de Hudaybiyya?", ["Umm Salama", "'Aisha", "Hafsa", "Zaynab bint Jahsh"], "Umm Salama aconselhou o Profeta ﷺ a sair e realizar ele próprio o sacrifício e o rapar do cabelo: os companheiros seguiram-no de imediato."),
"sira_201": ("Qual é o nome completo do Profeta ﷺ, até ao seu avô?", ["Muhammad ibn 'Abdillah ibn 'Abd al-Muttalib", "Muhammad ibn Abi Talib", "Muhammad ibn al-'Abbas", "Muhammad ibn Hashim"], "É Muhammad, filho de 'Abdullah, filho de 'Abd al-Muttalib, da tribo de Quraish."),
"sira_202": ("Que outro nome do Profeta ﷺ, mencionado no Alcorão por 'Isa, significa «o mais digno de louvor»?", ["Ahmad", "Al-Mustafa", "Al-Amin", "Abu-l-Qasim"], "'Isa anunciou um mensageiro que viria depois dele «cujo nome é Ahmad» (Alcorão 61:6)."),
"sira_203": ("Quanto tempo durou a revelação do Alcorão ao Profeta ﷺ?", ["Cerca de vinte e três anos", "Dez anos", "Quarenta anos", "Uma única noite"], "A revelação estendeu-se por cerca de vinte e três anos: treze em Meca e dez em Medina."),
"sira_204": ("Que companheiro foi o primeiro homem livre e adulto a abraçar o islão?", ["Abu Bakr as-Siddiq", "'Umar ibn al-Khattab", "'Uthman ibn 'Affan", "Sa'd ibn Abi Waqqas"], "Entre os homens livres e adultos, Abu Bakr foi o primeiro a responder ao apelo do Profeta ﷺ."),
"sira_205": ("Que criança foi a primeira a abraçar o islão?", ["'Ali ibn Abi Talib", "Anas ibn Malik", "Usama ibn Zayd", "'Abdullah ibn 'Umar"], "'Ali ibn Abi Talib, criado na casa do Profeta ﷺ, foi o primeiro das crianças a crer."),
"sira_206": ("Que liberto do Profeta ﷺ foi o primeiro dos libertos a abraçar o islão?", ["Zayd ibn Haritha", "Bilal ibn Rabah", "Suhayb ar-Rumi", "Salman al-Farisi"], "Zayd ibn Haritha, libertado e criado como um filho pelo Profeta ﷺ, foi o primeiro dos libertos a crer."),
"sira_207": ("Que versículo pôs fim à adoção legal, dizendo que o Profeta ﷺ não é pai de nenhum dos seus homens?", ["«Muhammad não é pai de nenhum dos vossos homens, mas o Mensageiro de Allah e o selo dos profetas»", "«Chamai-os pelos seus pais»", "«Os laços de sangue prevalecem»", "«Não adoteis»"], "«Muhammad não é pai de nenhum dos vossos homens, mas o Mensageiro de Allah e o último dos profetas»."),
"sira_208": ("Em que dia da semana se reúnem os muçulmanos para a oração comunitária instituída em Medina?", ["Na sexta-feira", "No sábado", "No domingo", "Na segunda-feira"], "A oração de sexta-feira (al-jumu'a) foi instituída em Medina e reúne a comunidade todas as semanas."),
"sira_209": ("Que companheiro dirigiu a oração durante a última doença do Profeta ﷺ, por ordem sua?", ["Abu Bakr as-Siddiq", "'Umar ibn al-Khattab", "'Ali ibn Abi Talib", "Bilal"], "O Profeta ﷺ ordenou que Abu Bakr dirigisse a oração durante a sua doença; os companheiros viram nisso um sinal."),
"sira_210": ("Que califa foi ferido de morte enquanto dirigia a oração da alvorada?", ["'Umar ibn al-Khattab", "Abu Bakr", "'Ali ibn Abi Talib", "Mu'awiya"], "'Umar ibn al-Khattab foi ferido durante a oração do fajr em Medina e morreu dos ferimentos."),
"sira_211": ("Quanto durou o califado de Abu Bakr?", ["Cerca de dois anos", "Dez anos", "Vinte anos", "Trinta anos"], "Abu Bakr governou cerca de dois anos antes da sua morte, e 'Umar sucedeu-lhe."),
"sira_212": ("Contra que movimento teve Abu Bakr de agir no início do seu califado?", ["A recusa do zakat e a apostasia de algumas tribos", "Uma invasão vinda da Pérsia", "Uma fome", "Uma revolta em Medina"], "O primeiro califado abriu-se com as chamadas guerras da ridda, contra as tribos que recusaram o zakat ou abandonaram o islão."),
"sira_213": ("Que título adotou 'Umar ibn al-Khattab como chefe da comunidade?", ["Amir al-Mu'minin (comandante dos crentes)", "Sultão", "Malik", "Imam al-Haramayn"], "O título de amir al-mu'minin estabeleceu-se com 'Umar e foi usado pelos califas seguintes."),
"sira_214": ("Que mesquita de Jerusalém foi a primeira alquibla dos muçulmanos?", ["A mesquita de Al-Aqsa", "A mesquita de Quba", "A mesquita do Profeta ﷺ", "A Mesquita Sagrada"], "Os muçulmanos oraram primeiro em direção a Jerusalém, antes de a alquibla ser fixada para a Caaba."),
"sira_215": ("Quais são as três mesquitas para as quais é especialmente recomendado viajar?", ["A Mesquita Sagrada, a mesquita do Profeta ﷺ e Al-Aqsa", "Quba, Al-Aqsa e Kufa", "A Mesquita Sagrada, Quba e Damasco", "Al-Aqsa, Kufa e Baçorá"], "É especialmente recomendado viajar a três mesquitas: a Mesquita Sagrada, a mesquita do Profeta ﷺ e a mesquita de Al-Aqsa."),
"sira_216": ("Onde proferiu o Profeta ﷺ o seu sermão de despedida, no dia de 'Arafa?", ["No vale de 'Urana, no monte 'Arafat", "Em Mina", "Diante da Caaba", "Em Muzdalifa"], "O sermão de despedida foi proferido no dia de 'Arafa, no vale de 'Urana, ao pé do monte 'Arafat."),
"sira_217": ("O que declarou o Profeta ﷺ inviolável no seu sermão de despedida?", ["O sangue, os bens e a honra de cada um", "As rotas comerciais", "Os poços de Medina", "Os palmares"], "Declarou sagrados o sangue, os bens e a honra dos muçulmanos, tal como são sagrados aquele dia, aquele mês e aquela cidade."),
"sira_218": ("O que deixou o Profeta ﷺ à sua comunidade, segundo o seu sermão de despedida, para que não se extraviasse?", ["O Livro de Allah", "Um tesouro", "Um exército", "Um mapa"], "Lembrou-lhes que deixava entre eles aquilo a que se agarrar para não se extraviarem: o Livro de Allah."),
"sira_219": ("Em que mês do calendário muçulmano se realiza a peregrinação, cumprida pelo Profeta ﷺ na sua despedida?", ["Dhul-Hijja", "Ramadão", "Muharram", "Rajab"], "A peregrinação de despedida teve lugar em Dhul-Hijja do ano 10 da Hégira."),
"sira_220": ("Quem lavou e amortalhou o corpo do Profeta ﷺ após a sua morte?", ["Os da sua casa, entre eles 'Ali e al-'Abbas", "Só os ansar", "Bilal e Anas", "O povo de Quba"], "Encarregou-se disso a sua própria família, entre eles 'Ali ibn Abi Talib e o seu tio al-'Abbas."),
"sira_221": ("Em que mês do ano hegírico morreu o Profeta ﷺ?", ["Rabi' al-Awwal", "Ramadão", "Shawwal", "Dhul-Qa'da"], "O Profeta ﷺ morreu em Medina no mês de Rabi' al-Awwal do ano 11 da Hégira."),
"sira_222": ("Que versículo recitou Abu Bakr para lembrar que o Profeta ﷺ era mortal?", ["«Muhammad não é senão um mensageiro; antes dele passaram outros mensageiros»", "«Enviámos-te como misericórdia»", "«És de um carácter eminente»", "«Quando chegar o socorro de Allah»"], "«Muhammad não é senão um mensageiro; antes dele passaram outros mensageiros. Se morresse ou fosse morto, voltaríeis sobre os vossos passos?»"),
"sira_223": ("Que companheiro é conhecido sobretudo pela quantidade de hadices que memorizou?", ["Abu Hurayra", "Anas ibn Malik", "Jabir ibn 'Abdillah", "Abu Sa'id al-Khudri"], "Abu Hurayra passou os últimos anos da vida do Profeta ﷺ a seu lado e foi o transmissor mais prolífico de hadices."),
"sira_224": ("Que companheiro, primo do Profeta ﷺ, se tornou a grande autoridade em exegese alcorânica?", ["'Abdullah ibn 'Abbas", "'Abdullah ibn 'Umar", "'Abdullah ibn Mas'ud", "'Abdullah ibn az-Zubayr"], "'Abdullah ibn 'Abbas, por quem o Profeta ﷺ pediu a compreensão do Livro, foi chamado «o intérprete do Alcorão»."),
"sira_225": ("Que companheiro foi enviado pelo Profeta ﷺ como governador e juiz ao Iémen, e morreu jovem na Síria?", ["Mu'adh ibn Jabal", "Abu 'Ubayda ibn al-Jarrah", "'Amr ibn al-'As", "Khalid ibn al-Walid"], "Mu'adh ibn Jabal, sábio entre os companheiros, foi enviado ao Iémen e depois morreu na Síria ainda jovem."),
"sira_226": ("Que vale se estende entre as duas colinas de Safa e Marwa, percorridas durante a peregrinação?", ["O vale de Meca, à volta da Caaba", "O vale de 'Urana", "O vale de Mina", "O vale de Badr"], "Safa e Marwa são duas pequenas colinas do vale de Meca, hoje incluídas dentro da Mesquita Sagrada."),
"sira_227": ("Que duas grandes tribos árabes de Medina se faziam guerra antes da chegada do Profeta ﷺ?", ["Os Aws e os Khazraj", "Quraish e Hawazin", "Thaqif e Kinana", "Tamim e Bakr"], "Os Aws e os Khazraj, inimigos durante muito tempo, formaram juntos os ansar após a chegada do Profeta ﷺ."),
"sira_228": ("Que versículo recorda aos ansar que eram inimigos e que Allah uniu os seus corações?", ["«Éreis inimigos e Ele uniu os vossos corações»", "«Éreis pobres»", "«Éreis poucos»", "«Estáveis perdidos»"], "«Lembrai o favor de Allah convosco: éreis inimigos e Ele uniu os vossos corações, e pelo Seu favor tornastes-vos irmãos»."),
"sira_229": ("Como elogia o Alcorão os ansar no seu acolhimento aos emigrados?", ["Preferem-nos a si próprios, mesmo estando necessitados", "Venderam-lhes terras", "Emprestaram-lhes dinheiro", "Alojaram-nos fora da cidade"], "«E preferem-nos a si próprios, ainda que estejam necessitados. Quem se guardar da sua própria avareza, esses são os bem-sucedidos»."),
"sira_230": ("Como se chama o conjunto de ditos, atos e aprovações do Profeta ﷺ?", ["A Suna", "O Alcorão", "A Sira", "O Tafsir"], "A Suna é o que o Profeta ﷺ disse, fez ou aprovou; a Sira é o relato da sua vida."),
"sira_231": ("Como se chama a geração que se seguiu à dos companheiros?", ["Os tabi'un (os seguidores)", "Os ansar", "Os muhajirun", "Os qurra'"], "Os tabi'un são aqueles que conheceram os companheiros sem terem visto o Profeta ﷺ."),
"sira_232": ("Como se chama a cadeia de transmissores de um hadice?", ["O isnad", "O matn", "O tafsir", "O tajwid"], "O isnad é a cadeia de transmissão; o matn é o próprio texto do hadice."),
"sira_233": ("Quais são as duas coletâneas de hadices tidas como as mais rigorosas, chamadas «os dois Sahih»?", ["Sahih al-Bukhari e Sahih Muslim", "Os Sunan de Abu Dawud e at-Tirmidhi", "O Muwatta' e o Musnad", "Os Sunan de an-Nasa'i e Ibn Maja"], "Sahih al-Bukhari e Sahih Muslim são conhecidos em conjunto como «os dois Sahih» (as-sahihan)."),
"sira_234": ("Em que cidade se encontram a mesquita do Profeta ﷺ e o seu túmulo?", ["Medina", "Meca", "Jerusalém", "Taif"], "A mesquita do Profeta ﷺ e o seu túmulo estão em Medina, a cidade da Hégira."),
"sira_235": ("Que epíteto tem Medina, em relação à luz que lhe é atribuída?", ["Al-Madina al-Munawwara (a cidade iluminada)", "Umm al-Qura", "Dar as-Salam", "Al-Mada'in"], "Medina é chamada al-Munawwara; Meca, por seu lado, é chamada al-Mukarrama."),
"sira_236": ("Que nome dá o Alcorão a Meca, «a mãe das cidades»?", ["Umm al-Qura", "Al-Madina", "Al-Balad al-Amin", "Bakka"], "«…para que adviras a mãe das cidades (Umm al-Qura) e os que estão à sua volta»."),
"sira_237": ("Qual era o ofício de Khadija, primeira esposa do Profeta ﷺ?", ["Comerciante", "Médica", "Poetisa", "Tecelã"], "Khadija bint Khuwaylid era uma comerciante respeitada de Meca, que confiou a sua caravana ao jovem Muhammad ﷺ."),
"sira_238": ("Quanto tempo esteve o Profeta ﷺ casado apenas com Khadija?", ["Até à morte dela; não casou com nenhuma outra em vida dela", "Dois anos", "Cinco anos", "Casou com outras logo a seguir"], "O Profeta ﷺ não casou com nenhuma outra mulher enquanto Khadija viveu; os outros casamentos vieram depois da sua morte."),
"sira_239": ("Como se chama o tio do Profeta ﷺ que o protegeu sem abraçar o islão?", ["Abu Talib", "Hamza", "Al-'Abbas", "Abu Lahab"], "Abu Talib, pai de 'Ali, protegeu o sobrinho contra Quraish até à sua morte."),
"sira_240": ("Que tio do Profeta ﷺ foi feito prisioneiro em Badr antes de abraçar o islão?", ["Al-'Abbas ibn 'Abd al-Muttalib", "Abu Talib", "Hamza", "Az-Zubayr ibn 'Abd al-Muttalib"], "Al-'Abbas, tio do Profeta ﷺ e antepassado dos abássidas, foi capturado em Badr e depois abraçou o islão."),
"sira_241": ("Como se chamam os companheiros que participaram na batalha de Badr?", ["Os badritas (badriyyun)", "Os ansar", "Os muhajirun", "Os uhuditas"], "Os companheiros presentes em Badr são conhecidos como badriyyun, e esse mérito é-lhes próprio."),
"sira_242": ("Que parte do espólio reserva o Alcorão para Allah, o Mensageiro, os parentes, os órfãos, os pobres e o viajante?", ["O quinto", "A metade", "O décimo", "O terço"], "«Sabei que de todo espólio que tomeis, um quinto é para Allah, para o Mensageiro, para os parentes, os órfãos, os pobres e o viajante»."),
"sira_243": ("Que versículo, ligado ao sermão de despedida, funda a igualdade dos povos perante Allah?", ["«O mais nobre de vós perante Allah é o mais piedoso»", "«Os homens vêm de um só pai»", "«Ninguém carrega o fardo alheio»", "«Não há coação na religião»"], "«Ó homens, criámo-vos de um varão e de uma fêmea… o mais nobre de vós perante Allah é o mais piedoso»."),
"sira_244": ("Quantos participaram no segundo pacto de 'Aqaba, o encontro decisivo com o povo de Yathrib?", ["Uma delegação de mais de setenta pessoas", "Três", "Dez", "Quinhentos"], "O segundo pacto de 'Aqaba reuniu uma delegação de mais de setenta homens e mulheres de Yathrib."),
"sira_245": ("Quantos naqibs (responsáveis) mandou o Profeta ﷺ designar entre o povo de Yathrib no pacto de 'Aqaba?", ["Doze", "Quatro", "Sete", "Vinte"], "Foram escolhidos doze naqibs para representar os grupos da delegação de Yathrib e responder pelo seu compromisso."),
"sira_246": ("Que nome tomou Medina depois da Hégira?", ["Madinat an-Nabi, a cidade do Profeta ﷺ", "Yathrib", "Só Tayba", "Al-Qura"], "Yathrib passou a chamar-se Madinat an-Nabi, «a cidade do Profeta ﷺ», abreviado para al-Madina."),
"sira_247": ("Que califa mandou copiar o Alcorão em exemplares oficiais enviados às províncias?", ["'Uthman ibn 'Affan", "Abu Bakr", "'Umar", "'Ali"], "Abu Bakr mandou reunir o texto; 'Uthman mandou fazer cópias oficiais e enviou-as às grandes cidades."),
"sira_248": ("Em que língua foi revelado o Alcorão ao Profeta ﷺ?", ["Em árabe", "Em aramaico", "Em persa", "Em grego"], "O Alcorão foi revelado em língua árabe clara, a do próprio povo do Profeta ﷺ."),
"sira_249": ("A que companheiro enviou o Profeta ﷺ ao Barém, regressando com o seu tributo?", ["Abu 'Ubayda ibn al-Jarrah", "Bilal", "Anas ibn Malik", "Abu Dharr"], "Abu 'Ubayda ibn al-Jarrah, chamado «o homem de confiança desta comunidade», regressou do Barém com o seu tributo."),
"sira_250": ("Que acontecimento marca o início do calendário muçulmano?", ["A Hégira de Meca para Medina", "O nascimento do Profeta ﷺ", "A primeira revelação", "A conquista de Meca"], "O calendário hegírico começa com o ano da Hégira, decisão tomada durante o califado de 'Umar."),
}
